/**
 * This is theming config file.
 * Supported themes are "cf" (carbon-fiber), "light" (JATO-Light), "dark" (JATO-Dark).
 * Default theme is "cf" (carbonfiber).
 */
csui.define('smart/themes/theming',['module'], function (module) {

    const DEFAULT_THEME = "cf";
    const JATO_DARK = "dark";
    const JATO_LIGHT = "light";
    const DEFAULT_VALUE_FOR_ENABLE_THEME_SELECTION = true;  // make it false to disable theme selection by default on burger menu.

    const APPLY_DEFAULT = true; // required theme attributes will be applied to defaul element, ie., document.body.

    const themes = {
        DEFAULT_THEME,
        JATO_DARK,
        JATO_LIGHT
    };

    const defaultConfig = {
        theme: DEFAULT_THEME,
        enableThemeSelection: DEFAULT_VALUE_FOR_ENABLE_THEME_SELECTION,
        applyDefault: APPLY_DEFAULT
    };

    const moduleConfig = module.config() ?? {};
    let themingConfig = { ...defaultConfig, ...moduleConfig };

    const SUPPORTED_THEMES = [DEFAULT_THEME, JATO_DARK, JATO_LIGHT];

    /**
     * This method returns theming module configuration.
     * 
     * @returns configuration object
     */
    const getConfig = () => {
        return themingConfig;
    };

    /**
     * This method returns the theme name which is currently applied.
     * 
     * @returns theme name
     */
    const getTheme = () => {
        const config = getConfig();
        let theme = config['theme'] ?? '';
        theme = theme.toLowerCase();
        theme = SUPPORTED_THEMES.indexOf(theme) === -1 ? DEFAULT_THEME : theme;
        return theme;
    };

    /**
     * Depricated: Instead use, saveTheme(themeValue);
     * @param {*} theme 
     */
    const storeTheme = (theme = DEFAULT_THEME) => {
        saveTheme(theme);
    }

    /**
     * This is an experimental feature to store selected theme at client browser.
     */
    const saveTheme = (theme = DEFAULT_THEME) => {
        themingConfig['theme'] = theme;
    };

    /**
     * This method applies the theme to the given element otherwise html tag.
     * And also applies given theme name, if nothing has passed as argument, default config theme gets applied.
     */
    const applyTheme = (element, themeName) => {
        const config = getConfig();
        if (element === undefined && config.applyDefault) {
            element = document.documentElement;
        }

        const theme = themeName ?? getTheme();
        element && (element.dataset.smartTheme = theme);
    };

    /**
     * This method returs true if the current theme is either JATO-Light or JATO-Dark.
     */
    const isJATOTheme = () => {
        const theme = getTheme();
        return theme !== DEFAULT_THEME;
    };

    const isThemeSelectionEnabled = () => {
        return getConfig().enableThemeSelection;
    }

    return {
        getTheme,
        applyTheme,
        isJATOTheme,
        themes,
        isThemeSelectionEnabled,
        saveTheme,
        storeTheme
    }

});

