csui.define('smart/controls/globalmessage/impl/messagedialog.view',[
  'nuc/lib/underscore', 'nuc/lib/jquery', 'nuc/lib/marionette', 'i18n',
  'i18n!smart/controls/globalmessage/impl/nls/globalmessage.lang',  
  'smart/themes/theming',
  'smart/themes/jato.icons/smart.jato.action.icons',
  'smart/themes/jato.icons/smart.jato.status.icons',
  'hbs!smart/controls/globalmessage/impl/messagedialog',
  'smart/controls/icons.v2/icons.v2',
  'smart/themes/carbonfiber/ot-icons/icons_smart_notification',
  'smart/themes/carbonfiber/ot-icons/icons_smart_action_16',
  'css!smart/controls/globalmessage/impl/messagedialog',
], function (_, $, Marionette, i18n, lang, theming, jatoIcons, jatoStateIcons, template, css) {
  'use strict';

  var messageClassMap = {
    info: "csui-info",
    success: "csui-success",
    success_with_link: "csui-success-with-link",
    warning: "csui-warning",
    error: "csui-error",
    processing: "csui-processing",
    none: "csui-none"
  };

  const __getStateIconsMap = () => {
    return {
      info: theming.isJATOTheme() ? jatoStateIcons.statusInfo : "smart_notification:notification_information24",
      success: theming.isJATOTheme() ? jatoStateIcons.statusSuccess : "smart_notification:notification_success24",
      success_with_link: theming.isJATOTheme() ? jatoStateIcons.statusSuccess : "smart_notification:notification_success24",
      warning: theming.isJATOTheme() ? jatoStateIcons.statusWarning : "smart_notification:notification_warning24",
      error: theming.isJATOTheme() ? jatoStateIcons.statusError : "smart_notification:notification_error24",
      processing: null,
      none: null
    };
  };

  var className = "csui-messagepanel";

  var View = Marionette.ItemView.extend({

    constructor: function MessageDialog(options) {
      this.css = css;
      options.info || (options.info = "info");
      this.className = className + " " + messageClassMap[options.info] + " " + (!options.details ? 'smart-no-details' : '');

      if (options.context && options.nextNodeModelFactory) {
        this._nextNode = options.context.getModel(options.nextNodeModelFactory);
      }

      Marionette.ItemView.prototype.constructor.call(this, options);
    },

    className: className + " " + messageClassMap["info"],
    template: template,

    ui: {
      closeAction: '.csui-header .smart-action-close',
      collapseAction: '.csui-header .smart-action-fewerdetails',
      expandAction: '.csui-header .smart-action-moredetails',
      stateIcon: '.smart-state-icon',
      closeIcon: '.smart-action-close',
      messageLink: '.csui-message-link',
      gotoLocation: '.csui-gotolocation-url'
    },

    events: {
      'click @ui.closeAction': 'doClose',
      'click @ui.collapseAction': 'doCollapse',
      'click @ui.expandAction': 'doExpand',
      'click @ui.messageLink': 'onClickLink',
      'click @ui.gotoLocation': 'onClickGotoLocation'
    },

    /*
    doResize: function () {
      var header = this.$el.find(".csui-header");
      var details = this.$el.find(".csui-details");
      details.width(header.outerWidth());
      if (this.options.sizeToParentContainer) {
        var width = this.$el.width();
        var parentWidth = this.$el.parent().width();
        var translateX = (parentWidth - width) / 2;
        translateX > 0 || (translateX = 0);
        //translateX = !!i18n.settings.rtl ? -translateX : translateX;
        translateX = 'translateX(' + translateX + 'px)';
        this.$el.css({'transform': translateX});
      }
    },*/

    doCollapse: function (animated) {
      this._clearTimeout();
      animated = (animated === false) ? false : true;
      var details = this.$el.find(".csui-details");
      var detailsText = details.find(".csui-text");
      var header = this.$el.find(".csui-header");
      this.options.messageHelper.switchField(header, ".csui-action", "moredetails",
          ["moredetails", "fewerdetails"]);
      this.ui.collapseAction.addClass('binf-hidden');
      this.ui.expandAction.removeClass('binf-hidden');
      var panel = _.extend({csuiAfterHide: function () { details.css("width", ""); }},
          this);
      this.options.messageHelper.collapsePanel(panel, details, detailsText, animated);
      this.stateExpandCollapse = "collapsed";
      this.ui.expandAction.focus();
    },

    doExpand: function (animated) {
      this._clearTimeout();
      animated = (animated === false) ? false : true;
      var details = this.$el.find(".csui-details");
      var detailsText = details.find(".csui-text");
      var header = this.$el.find(".csui-header");
      this.options.messageHelper.switchField(header, ".csui-action", "fewerdetails",
          ["moredetails", "fewerdetails"]);
      this.ui.expandAction.addClass('binf-hidden');
      this.ui.collapseAction.removeClass('binf-hidden');
      details.css("width", this.$el.find(".csui-header").outerWidth());
      this.options.messageHelper.expandPanel(this, details, detailsText, animated);
      this.stateExpandCollapse = "expanded";
      this.ui.collapseAction.focus();
    },

    doShow: function (relatedView, parentView) {
      var existingDialogs = parentView.$el.find('.csui-global-message.position-show');
      if (existingDialogs.length) {
        var existingDialogCount = existingDialogs.length,
          currentDialogHeader = this.$el.find('.csui-header');

        currentDialogHeader.css({
          'top': 4 * existingDialogCount + 'px',
          'margin': '0 ' + (-8 * existingDialogCount) + 'px'
        });
        var currentDialogDetailsWrapper = this.$el.find('.csui-details-wrapper'),
          currentDialogDetailsContainer = currentDialogDetailsWrapper.find('.csui-details');

        // Adding dynamic id to current dialog details container to fix accessibility violation issue with same id in DOM for stacked messages
        currentDialogDetailsContainer && currentDialogDetailsContainer.attr('id', `${currentDialogDetailsContainer.attr('id')}_${existingDialogs.length}`);

        if (currentDialogDetailsWrapper.length) {
          currentDialogDetailsWrapper.css({
            'margin-right': (-8 * existingDialogCount) + (-5) + 'px',
            'margin-left': (-8 * existingDialogCount) + (-5) + 'px',
            // details-wrapper should have same margin-top value as top for header. Fixes SVF-2470
            'margin-top': (4 * existingDialogCount) + 'px'
          });
        }
        // link-div was not extending fully as per header width, gave calculated margins to fix. Fixes SVF-2470
        var currentDialogLinkDiv = this.$el.find('.csui-message-link-div');
        if(currentDialogLinkDiv.length) {
          currentDialogLinkDiv.css({
            'margin-right': (-8 * existingDialogCount) + 'px',
            'margin-left': (-8 * existingDialogCount) + 'px',
            'margin-top': (4 * existingDialogCount) + 'px',
          });
        }
      }
      if (this.options.info === "success") {
        var self = this;
        var panel = _.extend({
          csuiAfterShow: function () {
            //self.doResize();
            self._setTimeout();
          }
        }, this);
        this.options.messageHelper.showPanel(panel, relatedView, parentView);
      } else {
        this.options.messageHelper.showPanel(this, relatedView, parentView);
      }
      //this.doResize();

      // Fire message show to make this message dialog tabbale
      this.$el.trigger('globalmessage.shown', this);
      if(this.options.details) {
        if(this.stateExpandCollapse === 'expanded') {
          this.ui.collapseAction[0] && this.ui.collapseAction[0].focus();
        }else {
          this.ui.expandAction[0] && this.ui.expandAction[0].focus();
        }
      }else {
        this.ui.closeAction.focus();
      }
    },

    doClose: function () {
      this._clearTimeout();
      var self = this, panel = _.extend({
        csuiAfterHide: function () {
          self.destroy();
          // Set focus back to Origin element which trigger the alert
          self.trigger('escaped:focus');
        }
      }, this);
      this.options.messageHelper.fadeoutPanel(panel);
    },

    _setTimeout: function () {
      var self = this;
      if (!this.options.enablePermanentHeaderMessages) {
        if (this.options.doAutoClose === undefined || (typeof this.options.doAutoClose === 'boolean' 
          && this.options.doAutoClose)) {
          // at least the fixed timeout can be deactivated, to comply with BITV 2.2.1a, configurable time limits
          var timeout = this.options.autoCloseTimeout || 5000;

          this.options.timeout = window.setTimeout(function () {
            self.doClose();
          }, timeout);
        }
      }
    },

    _clearTimeout: function () {
      if (this.options.timeout) {
        window.clearTimeout(this.options.timeout);
        this.options.timeout = undefined;
      }
    },

    headerId: undefined,
    detailsId: undefined,

    templateHelpers: function () {
      var closeAria = lang.closeDialogAria;
      if (!this.headerId) {
        this.headerId = _.uniqueId('header');
      }
      if (!this.detailsId) {
        this.detailsId = this.options.details ? _.uniqueId('details') : undefined;
      }

      var info = {        
        isJATO: theming.isJATOTheme(),
        expandSVGContent: jatoIcons.actionChevronSmallDown,
        collapseSVGContent: jatoIcons.actionChevronSmallUp,
        closeSVGContent: jatoIcons.actionCloseSmall,
        header_text: this.options.message,
        headerId: this.headerId,
        details_text: this.options.details,
        detailsId: this.detailsId,
        action_moredetails: lang.MoreDetails,
        action_fewerdetails: lang.FewerDetails,
        expand: lang.MoreDetails,
        expandAria: lang.ExpandAria,
        collapse: lang.FewerDetails,
        collapseAria: lang.CollapseAria,
        closeDialog: lang.CloseDialog,
        closeDialogAria: closeAria,
        gotoLocation: this.options.gotoLocation,
        targetLocationUrl: this.options.targetLocationUrl,
        openInNewTabLink: this.options.openInNewTabLink,
        OpenInNewTabLinkAria: lang.OpenInNewTabLinkAria
      };

      if (this.options.link_url && this.options.targetFolder) {
        info = _.extend(info, {
          message_with_link: true,
          link_label: this.options.link_label || lang.GotoLocationLinkLabel,
          link_url: this.options.link_url
        });
      }

      return info;
    },

    onClickLink: function (event) {
      event.preventDefault();
      event.stopPropagation();
      // leading application has to take care from here
      // for example, executing default action for the current model.
    },

    onClickGotoLocation: function(e) {
      e.preventDefault();
      e.stopPropagation();
      this.doClose();
      var targetLocation = this.options.targetLocation;
      if (targetLocation && this._nextNode) {
        this._nextNode.set('id', targetLocation.id);
      }
    },

    onRender: function () {
      // Set proper role and related fields
      this.$el.attr('role', 'alertdialog');
      this.$el.attr('aria-labelledby', this.headerId);
      if (this.detailsId) {
        this.$el.attr('aria-describedby', this.detailsId);
      }

      // Apply the right state icon
    const stateIcon = this.ui.stateIcon[0];
    const iconMap = __getStateIconsMap();
    const icon = iconMap[this.options.info];
    const altText = this.options.info;

    if (icon) {
      theming.isJATOTheme()
        ? stateIcon.innerHTML = icon
        : stateIcon.setAttribute("icon", icon);
    } else {
      this.$el.addClass("csui-no-icon");
    }

      // Update collapse/expand
      if (!this.stateExpandCollapse) {
        // only on initial rendering collapse/expand and take state from template
        var arrow = this.$el.find(".csui-header .csui-action").find(
            ":not(.binf-hidden)");
        if (arrow.hasClass("csui-action-fewerdetails")) {
          this.doExpand(false);
        } else if (arrow.hasClass("csui-action-moredetails")) {
          this.doCollapse(false);
        }
      }
    }

  });

  return View;

});


csui.define('smart/controls/globalmessage/impl/custom.wrapper.view',[
  'nuc/lib/backbone', 'nuc/lib/marionette',
  'css!smart/controls/globalmessage/impl/messagedialog',
], function (Backbone, Marionette) {
  'use strict';

  var CustomWrapperView = Marionette.ItemView.extend({

    constructor: function CustomWrapperView(options) {
      Marionette.ItemView.prototype.constructor.call(this, options);

      var contentView = this.getOption('contentView');
      if (!(contentView instanceof Backbone.View)) {
        contentView = contentView.call(this);
      }
      this.view = contentView;

      this.listenTo(contentView, 'destroy', this.destroy);
      this.region = new Marionette.Region({el: this.el});
    },

    className: 'csui-messagepanel',

    template: false,

    onRender: function () {
      this.region.show(this.view);
    },

    onDestroy: function () {
      this.region.empty();
    },

    doShow: function (relatedView, parentView) {
      this.options.messageHelper.showPanel(this, relatedView, parentView);
    }

  });

  return CustomWrapperView;

});


