csui.define('smart/controls/globalmessage/globalmessage',['module',
  'nuc/lib/underscore', 'nuc/lib/jquery', 'nuc/lib/backbone',
  'nuc/utils/messagehelper', 'smart/utils/accessibility',
  'smart/controls/globalmessage/impl/messagedialog.view',
  'smart/controls/globalmessage/impl/custom.wrapper.view',
  'smart/controls/progresspanel/progresspanel',
  'smart/dialogs/modal.alert/modal.alert',
], function (module, _, $, Backbone, MessageHelper, Accessibility,
    MessageDialogView, CustomWrapperView, SmartProgressPanel) {
  'use strict';

  var config = module.config();
  _.defaults(config, {
    enablePermanentHeaderMessages: false
  });

  if (Accessibility.isAccessibleMode()) {
    config.enablePermanentHeaderMessages = true;
  }

  var messageHelper = new MessageHelper(),
      globals = {},
      hasDefaultRegion;

  var GlobalMessage = {

    setMessageRegionView: function (messageRegionView, options = {}) {
      this._cleanupPreviousMessageRegion();
      // Global messages span over the entire view height without these options
      options = _.defaults({}, options, {
        useClass: true,
        sizeToParentContainer: true
      });
      options.classes && (globals.classNames = options.classes);
      globals.relatedView = options.useClass ? undefined : messageRegionView;
      //Size to parent container instead of browser view port. This is needed for cases where the
      //global messaging and progress bar are to display within a widget.
      globals.sizeToParentContainer = options.sizeToParentContainer;
      globals.messageRegionView = messageRegionView;
    },

    setProgresspanelMessageRegionView: _.bind(
      SmartProgressPanel.setProgresspanelMessageRegionView,
      SmartProgressPanel
    ),

    /* Shows an error message in the global message location.
      @Params:
        - info - the type of the message:
          - "info" (default)
          - "success"
          - "success_with_link"
          - "warning"
          - "error"
          - "processing"
          - "none"
        - text - the message text
        - details - a detailed message text
        - options - object containing other options
     */
    showMessage: function (info, text, details, options) {
      if (options?.MessageDialogMixin) {
        options?.MessageDialogMixin?.mixin(MessageDialogView.prototype);
      }
      return this._showMessageDialogView(
          MessageDialogView,
        _.extend(
          {
            info: info,
            message: text,
            details: details,
            messageHelper: messageHelper,
            sizeToParentContainer: globals.sizeToParentContainer,
            enablePermanentHeaderMessages: options?.configOptions
              ?.enablePermanentHeaderMessages
              ? options.configOptions.enablePermanentHeaderMessages
              : config.enablePermanentHeaderMessages,
          },
          options
        )
      );
    },

    showCustomView: function (customView) {
      return this._showMessageDialogView(CustomWrapperView, {
        contentView: customView,
        messageHelper: messageHelper
      });
    },

    _showMessageDialogView: function (View, options) {
      this._ensureMessageRegion();
      var messageDialogView = messageHelper.activatePanel(
          messageHelper.createPanel(globals, View, options),
          globals.relatedView, globals.messageRegionView);
      this._addEventHandlers(messageDialogView);
      return messageDialogView;
    },

    _addEventHandlers: function (view) {
      // should listen to resize of region (only), but as this does not fire
      // we have to listen to window as well :-(.
      var resizeHandler = function () {
        messageHelper.resizePanel(view, globals.relatedView);
      };
      $(window).on('resize', resizeHandler);
      view.listenTo(globals.messageRegionView, 'resize', resizeHandler);
      view.once('before:destroy', function () {
        $(window).off('resize', resizeHandler);
        view.stopListening(globals.messageRegionView, 'resize', resizeHandler);
      });
    },

    _ensureMessageRegion: function () {
      if (globals.messageRegionView) {
        return;
      }

      // Reserve a view as big as the screen for high panels like
      // the progress panel.  No width - this is no modal backdrop.
      var modalContainer = $.fn.binf_modal.getDefaultContainer(),
          messageContainer = $('<div>', {'class': 'csui-message-container'}, {
            'style': 'position:absolute; top: 0; left: 0; width: 0; height: 100vh;'
          }).appendTo(modalContainer);
      globals.messageRegionView = new Backbone.View({el: messageContainer});
      hasDefaultRegion = true;
    },

    _cleanupPreviousMessageRegion: function () {
      if (hasDefaultRegion) {
        globals.messageRegionView.remove();
        hasDefaultRegion = false;
      }
      globals = {};
    }

  };

  return GlobalMessage;

});


csui.define('smart/controls/pagination/impl/keyevent.navigation',['nuc/lib/underscore', 'nuc/lib/jquery', 'smart/utils/smart.base'
], function (_, $, smartBase) {
  'use strict';

  var KeyEventNavigation = {
    isTabable: function () {
      if (smartBase.isVisibleInWindowViewport(this.ui.pageSizeMenu) ||
          smartBase.isVisibleInWindowViewport(this.ui.navPagingMenu)) {
        this.focusedElement = this.ui.dropDownMenu.is(':visible') ? this.ui.dropDownMenu :
                              this.ui.navPagingMenu.find('ul li:first-child .smart-page');
        return true;
      }
    },

    currentlyFocusedElement: function () {
      var activeChild = this.getActiveChild();
      return activeChild;
    },

    // Disabled arrow up, arrow down, page up and page down key events for pagetabs as they are not part of latest KN guidelines. Fixes SVF-3601
    // Keeping the commented code as of now. To be removed if not required in near future.
     /**
     * @param event
     *
     */
    onKeyInView: function (event) {
      var keyCode = event.keyCode,
       continueEvent = true,
       activeChild = this.getActiveChild();
       this.isKeyEvent = true;
      this.activeChild || (this.activeChild = this.focusedElement);
      if(event.altKey && (keyCode > 36 && keyCode < 41)){
        if(activeChild !== this.ui.dropDownMenu) {
          event.stopPropagation();
        }
        else {
          if(keyCode === 37 || keyCode === 39){
            event.stopPropagation();
          }
        }
        event.preventDefault();
      }
      switch (keyCode) {
      //Enter and space
      case 32:
      case 13:
        if (this.activeChild === this.ui.dropDownMenu) {
          continueEvent = true;
        }
        this.executeAction(this.activeChild, event);
        break;
      case 9:
        // add tabindex zero once focus is moved outof pagination
        if (this.activeChild !== this.focusedElement) {
          this.ui.dropDownMenu.attr('tabindex', '-1');
          this.activeChild.attr('tabindex', '0');
        } else {
          this.ui.dropDownMenu.attr('tabindex', '0');
        }
        break;
          //right arrow & down arrow
      case 39:
      case 40:
        var nextChild = this._getNextActiveChild();
        if ( activeChild === this.ui.dropDownMenu && keyCode === 40){
          break;
        }   
        nextChild &&  this.setNextActiveChild(nextChild);
        break;
          //left arrow & up arrow
      case 37:
      case 38:
        var prevChild = this._getPrevActiveChild();
        if ( prevChild === this.ui.dropDownMenu && keyCode === 38){
          break;
        }     
        this.activeChild.attr('tabindex', '-1');
        this.setNextActiveChild(prevChild);
        break;
      case 36:
        this._activateHomeElem();
        continueEvent = false;
        break;
          //end
      case 35:
        this._activateEndElem();
        continueEvent = false;
        break;
      }
      return continueEvent;
    },

    /**
     * @param activeChild
     *
     */
    executeAction: function (activeChild, e) {
      e.stopPropagation();
      e.preventDefault();
      if (activeChild) {
        const pageId = activeChild.attr('data-pageid'),
          nextPageMenu = activeChild.attr('data-slidepage');

        if(e && pageId && nextPageMenu) {
          e.currentTarget = activeChild;
          this.onPageControlClick(e);
        }else if (nextPageMenu) {
          var pageMenu = parseInt(nextPageMenu, 10);
          this.slidePageMenu(pageMenu);
          this.activeChild = this.ui.navPagingMenu.find('.clickableControl').first();
          this.activateChild(true, this.activeChild);
        }
        else if (pageId) {
          var pageNum = parseInt(pageId, 10);
          this.changePage(pageNum);
          this.activeChild.removeClass('csui-acc-focusable-active');
        }
      }
    },

     /**
     * @param setActive
     * @param activeChild
     */
    activateChild: function (setActive, activeChild) {
      activeChild || (activeChild = this.getActiveChild());
      if (setActive) {
        activeChild.addClass('csui-acc-focusable-active');
        if(this?.isKeyEvent) {
          activeChild.trigger('focus');
        }
      }
      else {
        activeChild.removeClass('csui-acc-focusable-active');
      }
    },

     /**
     * @param child
     */
    setActiveChild: function (child) {
      this.activeChild = child;
    },

    getActiveChild: function () {
      this.activeChild ||
      (this.activeChild = this.ui.dropDownMenu.is(':visible') ? this.ui.dropDownMenu :
                          this.ui.navPagingMenu.find('ul li:first-child .smart-page'));
      return this.activeChild;
    },

     /**
     * @param nextChild
     */
    setNextActiveChild: function (nextChild) {
      if (nextChild !== this.activeChild) {
        this.activateChild(false, this.activeChild);
        this.activateChild(true, nextChild);
        this.activeChild = nextChild;
      }
    },

    resetActiveChild: function () {
      var activeChild = this.activeChild;
      this.activateChild(false);
      this.activeChild = null;
      if (activeChild) {

        var pageId = activeChild.attr('data-pageid');
        var pageMenu = activeChild.attr('data-slidepage');

        if (pageId) {
          this.activeChild = this._updatedChildPosition(pageId, activeChild);
        }
        else if (pageMenu && (this.numSlideMenus > 1)) {
          var nextPageTab = activeChild.parent().prev();
          if (nextPageTab.length > 0) {
            nextPageTab = nextPageTab.find('.smart-page');
          }
          else {
            nextPageTab = activeChild.parent().next().find('.smart-page');
          }
          pageId = nextPageTab.attr('data-pageid');
          this.activeChild = this._updatedChildPosition(pageId, nextPageTab);
        }
      }
      if (smartBase.isVisibleInWindowViewport(this.ui.pageSizeMenu) ||
          smartBase.isVisibleInWindowViewport(this.ui.navPagingMenu)) {
        this.focusedElement = this.ui.dropDownMenu.is(':visible') ? this.ui.dropDownMenu :
                              this.ui.navPagingMenu.find('ul li:first-child .smart-page');
        this.activeChild || (this.activeChild = this.focusedElement);
      }
    },

     /**
      * @private
      * @param pageId
      * @param activeChild
      */
    _updatedChildPosition: function (pageId, activeChild) {
      pageId = parseInt(pageId, 10);
      if (this.totalCount > this.pageSize) {
        var numPages = this.numPages - 1;
        pageId = pageId > (numPages) ? numPages : pageId;
        var pageMenu = Math.floor(pageId / this.pageTabsPerMenu);
        if (pageMenu > 0) {
          this._initializePageTabMenu(true, true, pageMenu);
        }

        pageId += '';
        activeChild = _.find(this.ui.navPagingMenu.find('.smart-page'), function (child) {
          return $(child).attr('data-pageid') === pageId;
        });

        return $(activeChild);
      }
      return null;
    },

    /**
      * @private
      * 
      */
    _getPrevActiveChild: function () {
      var nextChild = this.focusedElement,
          activeChild = this.activeChild,
          activeEle = $(document.activeElement);

      //account for no paging tabs
      var nextSibling = activeChild.parent().prev().find('.clickableControl');
      if (!activeEle.is(activeChild)) {
        nextSibling = activeEle.parent().prev().find('.clickableControl');
      }
      if (nextSibling.length > 0) {
        nextChild = nextSibling;
        // remove tabindex for current active page
        if (!activeEle.hasClass('binf-dropdown-toggle') && activeEle.attr('tabindex') === '0') {
          activeEle.attr('tabindex', '-1');
          this.ui.dropDownMenu.attr('tabindex', '0');
        }
      }
      return nextChild;
    },

    /**
      * @private
      */
    _getNextActiveChild: function () {
      var nextChild = this.focusedElement,
          activeChild = this.activeChild,
          activeEle = $(document.activeElement);

      //account for no paging tabs
      var nextSibling = activeChild.parent().next().find('.clickableControl');

      if (!activeEle.is(activeChild)) {
        nextSibling = activeEle.parent().next().find('.clickableControl');
      }
      if (nextSibling.length > 0) {
        nextChild = nextSibling;
        // remove tabindex for current active page
        if (!activeEle.hasClass('binf-dropdown-toggle') && activeEle.attr('tabindex') === '0') {
          activeEle.attr('tabindex', '-1');
          this.ui.dropDownMenu.attr('tabindex', '0');
        }
      } else if (activeEle.hasClass('smart-dropdown-toggle')) {
        nextChild = this.ui.navPagingMenu.find('.smart-page').first();
      } else {
        nextChild = null;
      }
      return nextChild;
    },

    /**
      * @private
      */
    _activateHomeElem: function () {
      this.activeChild.attr('tabindex', '-1');
      this.activeChild = this._getFirstElem();
      this.activateChild(true, this.activeChild);
    },

    /**
      * @private
      */
    _activateEndElem: function () {      
      this.activeChild.attr('tabindex', '-1');
      this.activeChild = this._getLastElem();
      this.activateChild(true, this.activeChild);
    },

     /**
      * returns the last element in pagedropdown if opened, else last element in page navigation
      * @private
      */
    _getLastElem: function () {
      if(this.ui.dropDownMenu.parent().hasClass('binf-open')){
        return this.$el.find('.binf-dropdown ul > li:last-child > a ');
     } 
      return this.ui.navPagingMenu.find('.clickableControl').last();
    },

     /**
      * returns the first element in pagedropdown if opened, else first element in page navigation
      * @private
      */
      _getFirstElem: function () {
        if(this.ui.dropDownMenu.parent().hasClass('binf-open')){
           return this.$el.find('.binf-dropdown ul > li:first-child > a ');
        } 
        return this.ui.navPagingMenu.find('.clickableControl').first();
      },




  };

  return KeyEventNavigation;

});


