        this.ui.header.addClass('group--is-expanded');
        if (theming.isJATOTheme()) {
          this.ui.icon.attr('svg', jatoIcons.actionChevronSmallDown);
        } else {
          this.ui.icon.attr('icon', 'smart_action:action_caret_up32');
        }
