csui.define('smart/controls/table.settings/table.settings.columns.side.panel.view',['module', 'nuc/lib/underscore', 'nuc/lib/backbone', 'nuc/lib/marionette',
  'nuc/utils/log',
  'smart/controls/side.panel/side.panel.view',
  'smart/controls/table.settings/impl/columns.side.panel.selected.view',
  'smart/controls/table.settings/impl/columns.side.panel.edit.view',
  'smart/dialogs/modal.alert/modal.alert',
  'i18n!smart/controls/table.settings/impl/nls/lang',
  'css!smart/controls/table.settings/impl/columns.side.panel',
], function(module, _, Backbone, Marionette, logUtils,
  SidePanelView,
  ColumnsSidePanelSelectedView,
  ColumnsSidePanelEditView,
  ModalAlert,
  lang) {
  const log = logUtils(module.id);

  class TableSettingsColumnsSidePanelView {

    /**
     * Construct a new TableSettingsColumnsSidePanelView
     * @param options.allColumns - Array with model data or Backbone.Collection with all possible columns. Properties: key,
     * name, pinned, permanent, default. Pinned and permanent columns must also be in selectedColumns and can't be removed in the UI.
     * @param options.selectedColumns - Backbone.Collection for finally selected and ordered columns.
     * Can be prepopulated to let the UI show already customized column configuration. When selectedColumns is empty, the initial
     * set of models get copied from the default columns. First all columns with pinned=true are taken and then all columns where either
     * permanent or default is true.
     * @param options.ungroupedFirst - if true, the group with ungrouped columns will be shown
     *     first in edit screen. Otherwise, the Ungrouped group comes last.
     * @param options.haveOtherCustomizations - if true, enable Reset to default button regardless of other changes in sequence or selection
     */
    constructor(options) {
      const self = this;
      let allColumnsCollection;

      this._haveOtherCustomizations = options.haveOtherCustomizations;
      this._currentSlideIndex = -1;

      if (_.isArray(options.allColumns)) {
        allColumnsCollection = new Backbone.Collection(options.allColumns);
      } else {
        if (options.allColumns instanceof Backbone.Collection) {
          allColumnsCollection = options.allColumns;
        } else {
          throw new Error('options.allColumns must either be an Array with model data or a Backbone.Collection');
        }
      }
      if (!options.selectedColumns) {
        throw new Error('selectedColumns must not be undefined');
      }
      if (!(options.selectedColumns instanceof Backbone.Collection)) {
        throw new Error('selectedColumns must be a Backbone.Collection');
      }

      for (let i = allColumnsCollection.length - 1; i >= 0; i--) {
        const column = allColumnsCollection.at(i);
        if (column.get('permanent')) {
          column.set('permanentAtEnd', true, {silent: true});
        } else {
          break; // stop loop on first non-permanent column from the end
        }
      }

      this._columnsSelectedView = new ColumnsSidePanelSelectedView(
        { allColumns: allColumnsCollection, selectedColumns: options.selectedColumns });
      this._currentSelectedColumns = new Backbone.Collection();
      this._columnsEditView = new ColumnsSidePanelEditView(
        { allColumns: allColumnsCollection, selectedColumns: this._currentSelectedColumns, ungroupedFirst: options.ungroupedFirst });
      this._sidePanelView = new SidePanelView({
        sidePanelClassName: 'smart-side-panel-table-settings',
        layout: {
          size: 'custom',
        },
        hideNextButton: true,
        hideBackButton: false,
        beforeDestroyCallback: function() {
          return new Promise((resolve, reject) => {
            let mustAskForConfirmation = self._checkForChanges.call(self);

            if (mustAskForConfirmation) {
              const discardAllOptions = {
                lightWeight:true,
                buttons: {
                  showYes: true,
                  labelYes: lang.buttonTextDiscard,
                  showNo: false,
                  showCancel: true,
                },
              };
              ModalAlert.confirmWarning(lang.discardChangesTitle, '', discardAllOptions)
                .done(function() {
                  resolve(true);
                })
                .fail(function() {
                  resolve(false);
                });
            } else {
              resolve(true);
            }
          });
        },
        slides: [
          {
            title: lang.columnsTitleSelected,
            ariaDescription: lang.columnsAriaSelected,
            layout: {
              header: true,
              footer: true,
            },
            footer: {
              rightButtons: [
                {
                  label: lang.buttonTextApply,
                  id: 'apply',
                  key: 'apply',
                  variant: 'primary',
                  close: true,
                }, {
                  label: lang.buttonTextEdit,
                  id: 'edit',
                  key: 'edit',
                  variant: 'secondary',
                }, {
                  label: lang.buttonTextResetLong,
                  id: 'reset',
                  key: 'reset',
                  variant: 'secondary',
                },
              ],
            },
            content: this._columnsSelectedView,
          },
          {
            title: lang.columnsTitleEdit,
            ariaDescription: lang.columnsAriaEdit,
            layout: {
              header: true,
              footer: true,
            },
            footer: {
              hideBackButton: false,
              rightButtons: [
                {
                  label: lang.buttonTextUpdate,
                  id: 'update',
                  key: 'update',
                  variant: 'primary',
                },
              ],
            },
            content: this._columnsEditView,
          },
        ],
      });

      this._sidePanelView.slides[0].footer.rightButtons[0].disabled = true; // apply
      this._sidePanelView.slides[0].footer.rightButtons[2].disabled = true; // reset to default
      this._sidePanelView.slides[1].footer.rightButtons[0].disabled = true; // update
      this.listenTo(this._sidePanelView, 'after:hide', () => {
        this.trigger('hidden');
      });

      this.listenTo(this._sidePanelView, 'shown:slide', (slide, slideIndex) => {
        this._currentSlideIndex = slideIndex;
        for (let idx = 0; idx < this._sidePanelView.slides.length; idx++) {
          if (idx !== slideIndex) {
            this._sidePanelView.slides[idx].content.markShown(false);
          }
          switch (slideIndex) {
            case 0:
              this._selectedColumnsFooterView = this._sidePanelView.footerView;
              if (!this._initialSelectedColumnsHash) {
                this._initialSelectedColumnsHash = this._columnsSelectedView.getCurrentlySelectedColumnsHash();
              }
              this._enableOrDisableApplyButton();
              this._enableOrDisableResetToDefaultButton();
              break;
            case 1:
              this._editColumnsFooterView = this._sidePanelView.footerView;
              this._initialEditColumnsHash = this._columnsEditView.getCurrentlySelectedColumnsHash();
              break;
          }
        }
        // switch(slideIndex) {
        //   case 1:
        //     this._updateSubtitle();
        //     break;
        // }
        slide.content.markShown(true);
        slide.content.setInitialFocus();
      });
      this.listenTo(this._columnsSelectedView, 'button:click', (button, args) => {
        switch (button.key) {
          case 'apply':
            this._columnsSelectedView.applyChanges();

            // re-create the initial selected columns hash to skip the confirmation dialog (beforeDestroyCallback)
            this._initialSelectedColumnsHash = this._columnsSelectedView.getCurrentlySelectedColumnsHash();
            break;
          case 'edit':
            this._setCurrentlySelectedColumns();
            this._sidePanelView._showSlide(1);
            break;
          case 'reset':
            this._wantResetAllChanges().then((confirmed) => {
              if (confirmed) {
                if (this._haveOtherCustomizations) {
                  this._haveOtherCustomizationsReset = true;
                  this._haveOtherCustomizations = false;
                }
                this._columnsSelectedView.resetToDefaults();
              }
            });
            break;
        }
      });
      this.listenTo(this._columnsEditView, 'before:button:click', async (button, args) => {
        if (button.type === 'back') {
          let selectedEditColumnsHash = this._columnsEditView.getCurrentlySelectedColumnsHash();
          if (selectedEditColumnsHash === this._initialEditColumnsHash) {
            return; // no confirmation dialog needed if nothing has changed
          }

          // back button was pressed: show confirmation dialog if there were changes made in the edit view
          const keepDiscardOptions = {
            lightWeight: true,
            buttons: {
              showYes: true,
              labelYes: lang.buttonTextKeep,
              showNo: true,
              labelNo: lang.buttonTextDiscard,
              showCancel: true,
            },
          };
          args.wait = new Promise((resolve, reject) => {
            ModalAlert.confirmQuestion(lang.keepChangesTitle, '', keepDiscardOptions)
              .done(function() {
                // 1st button (keep) was clicked
                args.keep = true;
                resolve();
              })
              .fail(function(arg) {
                if (arg === undefined) {
                  // 3rd button (cancel) was clicked
                  args.cancel = true; // cancel the handling of the back button
                } else {
                  args.discard = true;
                  // 2nd button (discard) was clicked
                }
                resolve();
              });
          });
        }
      });
      this.listenTo(this._columnsEditView, 'button:click', (button, args) => {
        if (button.type === 'back') {
          if (args.keep) {
            // same as update button
            this._initialEditColumnsHash = this._columnsEditView.getCurrentlySelectedColumnsHash();
            this._columnsSelectedView.setCurrentSelectedColumns(this._columnsEditView.getSelectedColumns());
            return;
          }

          // discard: throw away changes in selected columns
          this._currentSelectedColumns.reset([]);
          return;
        }
        switch (button.key) {
          case 'update':
            this._sidePanelView._showSlide(0);
            this._initialEditColumnsHash = this._columnsEditView.getCurrentlySelectedColumnsHash();
            this._columnsSelectedView.setCurrentSelectedColumns(this._columnsEditView.getSelectedColumns());
            break;
        }
      });

      this.listenTo(this._currentSelectedColumns,
        'add remove', () => {
          // change event is triggered when selecting a column
          // change:selection is triggered when unselecting a column
          if (!this._initialEditColumnsHash) {
            return;
          }
          const editColumnsHash = this._columnsEditView.getCurrentlySelectedColumnsHash();
          const disabled = editColumnsHash === this._initialEditColumnsHash;

          // need to save the active element to be able to re-focus after updating the button,
          // which unfortunately performs the "old" kn-code that focuses some other element.
          const activeElementBeforeUpdateButton = document.activeElement;

          this._editColumnsFooterView.updateButton('update', { disabled: disabled });

          if (activeElementBeforeUpdateButton) {
            activeElementBeforeUpdateButton.focus(); // re-focus - see comment above
          }
        },
      );

      this.listenTo(this._columnsSelectedView.collection, 'update reset', () => {
        if (!this._initialSelectedColumnsHash) {
          return;
        }
        this._enableOrDisableApplyButton();
        this._enableOrDisableResetToDefaultButton();
      });
    }

    _enableOrDisableResetToDefaultButton() {
      const enabled = this._haveOtherCustomizations || !this.areSelectedColumnsDefault();

      // need to save the active element to be able to re-focus after updating the button,
      // which unfortunately performs the "old" kn-code that focuses some other element.
      const activeElementBeforeUpdateButton = document.activeElement;

      this._selectedColumnsFooterView.updateButton('reset', {disabled: !enabled});

      if (activeElementBeforeUpdateButton) {
        activeElementBeforeUpdateButton.focus(); // re-focus - see comment above
      }
    }

    _enableOrDisableApplyButton() {
      const selectedColumnsHash = this._columnsSelectedView.getCurrentlySelectedColumnsHash();
      const enabled = this._haveOtherCustomizationsReset || selectedColumnsHash !== this._initialSelectedColumnsHash;

      // need to save the active element to be able to re-focus after updating the button,
      // which unfortunately performs the "old" kn-code that focuses some other element.
      const activeElementBeforeUpdateButton = document.activeElement;

      this._selectedColumnsFooterView.updateButton('apply', {disabled: !enabled});

      if (activeElementBeforeUpdateButton) {
        activeElementBeforeUpdateButton.focus(); // re-focus - see comment above
      }
    }

    async _wantResetAllChanges() {
      const isResetToDefault = !this._haveOtherCustomizations && this.areSelectedColumnsDefault();

      return new Promise((resolve, reject) => {
        if (isResetToDefault) {
          resolve(true); // confirmed without asking, because nothing changed
        } else {
          const resetOptions = {
            buttons: {
              showYes: true,
              labelYes: lang.buttonTextReset,
              showNo: false,
              showCancel: true,
            },
          };
          ModalAlert.confirmWarning(lang.resetAllChanges, lang.resetAllChangesTitle, resetOptions)
            .done(function() {
              // 1st button (reset) was clicked
              resolve(true);
            })
            .fail(function() {
              resolve(false);
            });
        }
      });
    }

    _checkForChanges() {
      let mustAskForConfirmation = false;

      const selectedColumnsHash = this._columnsSelectedView.getCurrentlySelectedColumnsHash();
      if (selectedColumnsHash !== this._initialSelectedColumnsHash) {
        mustAskForConfirmation = true;
      } else {
        if (this._currentSlideIndex === 1 && this._initialEditColumnsHash) {
          const editColumnsHash = this._columnsEditView.getCurrentlySelectedColumnsHash();
          if (editColumnsHash !== this._initialEditColumnsHash) {
            mustAskForConfirmation = true;
          }
        }
      }
      return mustAskForConfirmation;
    }

    _updateSubtitle() {
      const selected = this._columnsEditView.collection.where({ selected: true });
      this._sidePanelView.slides[1].subTitle = `${selected.length} selected`;
      this._sidePanelView.slides[1].content.trigger('update:header', this._sidePanelView.slides[1]);
    }

    _setCurrentlySelectedColumns() {
      const models = this._columnsSelectedView.getSelectedColumns();
      this._currentSelectedColumns.reset(models);
    }

    show() {
      return new Promise((resolve, reject) => {
        this._sidePanelView.show(() => {
          this._columnsSelectedView.focusFirst();
          this.trigger('shown');
          resolve();
        });
      });
    }

    hide() {
      return new Promise((resolve, reject) => {
        this._sidePanelView.hide(() => {
          resolve();
        });
      });
    }

    areSelectedColumnsDefault() {
      return this._columnsSelectedView.areSelectedColumnsDefault();
    }
  }

  Object.assign(TableSettingsColumnsSidePanelView.prototype, Backbone.Events);

  return TableSettingsColumnsSidePanelView;
});


