csui.define('smart/controls/facet.panel/facet.panel.view',[
  "nuc/lib/underscore",
  "nuc/lib/jquery",
  "nuc/lib/marionette",
  "module",
  "smart/controls/facet.panel/impl/facet/facet.card.view",
  "smart/behaviors/keyboard.navigation/smart.tabable.region.behavior",
  "smart/controls/facet.panel/impl/facet.panel.key.navigation",
  "smart/controls/progressblocker/blocker",
  "smart/mixins/view.events.propagation/view.events.propagation.mixin",
  "hbs!smart/controls/facet.panel/impl/facet.panel",
  "i18n!smart/controls/facet.panel/impl/nls/lang",
  "smart/themes/theming",  
  "smart/themes/jato.icons/smart.jato.action.icons",
  "css!smart/controls/facet.panel/impl/facet.panel",
], function (
  _,
  $,
  Marionette,
  module,
  FacetCardView,
  TabableRegionBehavior,
  KeyEventNavigation,
  BlockingView,
  ViewEventsPropagationMixin,
  template,
  lang,
  theming,
  jatoIcons
) {
  "use strict";

  var config = module.config() || {};

  var FacetPanelView = Marionette.CompositeView.extend({
    template: template,

    className: "smart-facet-panel csui-normal-scrolling",

    behaviors: {
      TabableRegion: {
        behaviorClass: TabableRegionBehavior,
      },
    },

    childView: FacetCardView,
    childViewContainer: ".cs-list-group",

    childViewOptions: function () {
      return {
        blockingParentView: this.options.blockingParentView,
        context: this.options.context,
        facetOptions: this.options,
        parentView: this,
      };
    },

    childEvents: {
      "apply:filter": "applyFilter",
      "apply:addRemoveAll": "applyAll",
      "remove:filter": "removeFilter",
      "activate:facet": "setActiveFacet",
      "escape:focus": "resetFacetFocus",
      "fetch:more:facets": "fetchFacets",
    },

    events: {
      keydown: "onKeyInView",
      "click .smart-all-facet-toggler": "_onExpandAllBtnClick",
    },

    ui: {
      listPanel: ".smart-facet-list-panel",
      noResultsPanel: ".smart-facet-noresults-panel",
      loadingPanel: ".smart-facet-loading-panel",
    },

    templateHelpers: function () {
      var showTitle = this.options.data.showTitle;
      var title = this.options.data.title;
      var regionAria = this.options.data.regionAria;
      var showAllAria = this.options.data.showAllAria;
      var hideAllAria = this.options.data.hideAllAria;
      return {
        isJATO: theming.isJATOTheme(),
        showTitle: showTitle,
        title: title,
        regionAria: regionAria,
        showAllAria: showAllAria,
        hideAllAria: hideAllAria,
        noResultsFound: lang.emptyFacetMessage,
        loadingFacetMessage: lang.loadingFacetMessage,
        doubleUpIcon: jatoIcons.actionChevronDoubleUp,
        doubleDownIcon: jatoIcons.actionChevronDoubleDown,
      };
    },

    onAddChild: function (childView) {
      var $child = childView.$el,
        self = this,
        isJATO = theming.isJATOTheme();
      //Hide all children with index greater than the set number of items to show from server
      if (childView.getIndex() === this.collection.length - 1 && !isJATO) {
        $child.css("border-bottom", "0px");
      }
      $child.on("focus", function () {
        self.onSetNextChildFocus(childView);
      });
      this.propagateEventsToViews(childView);
    },

    constructor: function FacetPanelView(options) {
      options || (options = {});
      options.data || (options.data = {});
      this.originatingView = options.originatingView;
      this.showButtonsInEachFacet = 
        config.showButtonsInEachFacet ?? options.showButtonsInEachFacet ?? true;
      this.maxFacetSelection =
        config.maxFacetSelection ?? options.maxFacetSelection ?? 5;
      options.showButtonsInEachFacet = this.showButtonsInEachFacet;
      options.maxFacetSelection =
        this.maxFacetSelection <= 0 ? 1 : this.maxFacetSelection;
      Marionette.CompositeView.call(this, options);
      this.options.data.title = options?.facetPanelTitle || lang.facetsTitle;
      this.options.data.regionAria = lang.facetsRegionAria;
      this.options.data.showAllAria = lang.showAllAria;
      this.options.data.hideAllAria = lang.hideAllAria;

      /* Show title by default if not specified in options*/
      this.options.data.showTitle =
        this.options.showTitle === undefined ? true : this.options.showTitle;
      //This function is used in the keyevent.navigation to remove focus from a facet group once focus
      //falls outside the Facet Filter. Within keyevent.navigation 'onRemoveKeyboardFocus' is bound to the
      //browser Documents 'mousedown' event at the time of Tab entry.
      this._onRemoveKeyboardFocus = _.bind(this._removeKeyboardFocus, this);
      if (this.options.blockingParentView && !this.options.blockingLocal) {
        BlockingView.delegate(this, this.options.blockingParentView);
        this.listenTo(this.facets, "request", this._blockActions)
          .listenTo(this.facets, "sync", this._unblockActions)
          .listenTo(this.facets, "reset", this._unblockActions)
          .listenTo(this.facets, "error", this._unblockActions);
      } else {
        BlockingView.imbue({
          parent: this,
          local: this.options.blockingLocal,
        });
      }

      this.listenTo(this, "data:requested", this._blockActions);
      this.listenTo(this, "data:synced data:reset", this._unblockActions);
      this.listenTo(this, "data:error", this._unblockActionsWithError);

      this.listenTo(this.collection, "request", this._blockActions);
      this.listenTo(this.collection, "update reset sync", this._unblockActions);
      this.listenTo(this.collection, "error", this._unblockActionsWithError);
      this.expandAll = true;
      this.listenTo(this, "toggle:expand:all", this._toggleExpandAll);
      this.listenTo(this.facets, "mask:facetPanel:facetBar",
        _.bind(function (args) {
          if(args?.maskFacetPanel){
            this.$el.addClass("smart-non-clickable-facet");
          }
          else{
            this.$el.removeClass("smart-non-clickable-facet");
          }
        }, this)
      );
    },

    _toggleExpandAll: function(event) {   
      if(!this.expandAll) {
        this.el.querySelector(".smart-all-facet-open")?.classList.remove("binf-hidden");        
        event && this.el.querySelector(".smart-all-facet-open")?.focus();
        this.el.querySelector(".smart-all-facet-close")?.classList.add("binf-hidden");
      } else {
        this.el.querySelector(".smart-all-facet-open")?.classList.add("binf-hidden");
        this.el.querySelector(".smart-all-facet-close")?.classList.remove("binf-hidden");
        event && this.el.querySelector(".smart-all-facet-close")?.focus();
      }
    },    

    _onExpandAllBtnClick: function (event) {
			this.expandAll = !this.expandAll;
      this.trigger("toggle:expand:all", event);
		},

    _blockActions: function () {
      this.blockActions();

      // hide list view
      this.ui.listPanel.addClass("binf-hidden");

      // hide no-results view
      this.ui.noResultsPanel.addClass("binf-hidden");

      // show loading panel
      this.ui.loadingPanel.removeClass("binf-hidden");
    },

    _unblockActions: function () {
      /*  Handled scenarios where leading application do not have collection(facets) fetched value
       and facet panel is rendered */
      if((this.facets.fetched === undefined && this.isRendered) || this.facets.fetched) {
        this.unblockActions();

        // show list panel if collection length is > 0.
        this.ui.listPanel[
          this.collection.length > 0 ? "removeClass" : "addClass"
        ]("binf-hidden");

        // show no-results panel if collection length is 0.
        this.ui.noResultsPanel[
          this.collection.length === 0 ? "removeClass" : "addClass"
        ]("binf-hidden");

        // hide loading panel
        this.ui.loadingPanel.addClass("binf-hidden");
      }
    },
   
    _unblockActionsWithError: function () {
      this._unblockActions();
    },

    _toggleNoResultPanel: function () {
      if (this.collection?.length || this.collection?.error) {
        this.ui.noResultsPanel.addClass("binf-hidden");
      } else {
        this.ui.noResultsPanel.removeClass("binf-hidden");
      }
      this.ui.loadingPanel.addClass("binf-hidden");
    },

    isTabable: function () {
      return !(
        this.$el.parent().hasClass("binf-hidden") ||
        this.$el.parent().hasClass("csui-facetview-hidden")
      );
    },

    onRenderCollection: function () {
      this.trigger("refresh:tabindexes");
      this._toggleNoResultPanel();
      this._toggleExpandAll();
      //this.unblockActions();
    },

    onBeforeDestroy: function () {
      $(document).off("mousedown", this._onRemoveKeyboardFocus);
    },

    applyFilter: function (facet) {
      this.trigger("apply:filter", facet.newFilter);
    },

    applyAll: function (facet) {
      this.trigger("apply:all", facet.newFilter);
    },

    removeFilter: function (facet) {
      this.trigger("remove:filter", facet.newFilter);
    },

    //Set active facet and disable all others.
    setActiveFacet: function (facet) {
      if (facet.selectItems.length > 0 && this.showButtonsInEachFacet) {
        this.children.each(function (view) {
          if (view.getIndex() !== facet.getIndex()) {
            view.$el.find(".csui-facet-content").addClass("facet-disabled");
            view.$el.find(".csui-facet-footer").addClass("facet-disabled");
            let showMoreBtn = view.$el.find('.csui-facet-footer')[0].querySelectorAll('.smart-show-more');
            showMoreBtn.length!= 0 && showMoreBtn[0].setAttribute('disabled','');
          }
        });
      } else {
        this.$el.find(".csui-facet-content").removeClass("facet-disabled");
        this.$el.find(".csui-facet-footer").removeClass("facet-disabled");
        this.$el.find(".smart-show-more").removeAttr("disabled");
      }
    },

    // fetch more facets on clicking the show more link
    fetchFacets: function (childview) {
      this.trigger("fetch:more:facets", childview);
    },
  });

  _.extend(FacetPanelView.prototype, KeyEventNavigation);
  _.extend(FacetPanelView.prototype, ViewEventsPropagationMixin);
  return FacetPanelView;
});


csui.define('smart/utils/letter-avatar-random-color/letter-avatar-colors',['module'], function (module) {

    var config = {

        colors: ["#414979", "#2e3d98", "#4f3690", "#e00051", "#006353", "#007599", "#147bbc",
            "#a0006b", "#ba004C"]
    };

    var LetterAvatarColor = {

        getLetterAvatarColor: function (initials) {
            if (!initials) {
                return "";
            }
            var charIndex = 0,
                colourIndex = 0,
                initialsLen = initials.length;
            initials = initials.toUpperCase();
            for (var i = 0; i < initialsLen; i++) {
                charIndex += initials.charCodeAt(i);
            }
            colourIndex = parseInt(charIndex.toString().split('').pop());
            colourIndex = (colourIndex === 9) ? colourIndex - 1 : colourIndex;
            return config.colors[colourIndex];
        }
    };

    return LetterAvatarColor;

});


csui.define('smart/utils/user.avatar.color',['nuc/lib/underscore',
    'smart/utils/letter-avatar-random-color/letter-avatar-colors'
], function (_, LetterAvatarColor) {

    var UserAvatarColor = {

        getUserAvatarColor: function (user) {
            if (!user || _.isEmpty(user)) {
                return "";
            }
            var initials = (user.initials && user.initials.length > 1) ? user.initials : (user.name ? user.name.substring(0, 2) : "");
            return LetterAvatarColor.getLetterAvatarColor(initials);
        }

    };
    return UserAvatarColor;
});


