csui.define('smart/controls/app.header/panel/header/header.view',[
    "nuc/lib/jquery",
    "nuc/lib/underscore",
    "nuc/lib/marionette3",
    "smart/utils/smart.base",
    "hbs!smart/controls/app.header/panel/header/impl/header",
    "i18n!smart/controls/app.header/panel/impl/nls/lang",
    "smart/themes/theming",
    "smart/themes/jato.icons/smart.jato.app.header.icons"
], function ($, _, Marionette, SmartBase, template, lang, theming, jatoHeaderIcons) {
    "use strict";

    const isJato = () => theming.isJATOTheme();

    let SmartPanelHeaderView = Marionette.View.extend({

        template,

        templateContext: function () {
            let brandingConfig = this?.options?.brandingConfig?.attributes ?? {};
            let logoSrc = this.options.otcData.logosrc ?? brandingConfig.logoSrc ?? '';
            let iconAppearance = brandingConfig?.brandingSettingCodes?.iconThemes ?? '';
            iconAppearance = iconAppearance !== 'default' ? iconAppearance : 'light';
            const rtlClass = SmartBase.isRTL() ? "smart-hamburger-close-rtl-btn" : "";
            let messages = {
                rtlClass,
                isJato: isJato(),
                actionHamburgerClose: jatoHeaderIcons.actionHamburgerClose,
                logoSrc,
                iconAppearance,
                closeTitle: lang.closeMenuTitle,
                closeAriaLabel: lang.closeMenuTitle
            };
            return messages;
        },

        className: "smart-panel-header",

        ui: {
            collapseButton: 'otc-button',
            logo: '.smart-panel-header-logo'
        },
        events: {
            keydown: "onKeyInView",
        },

        constructor: function SmartPanelHeaderView(options = {}) {
            Marionette.View.apply(this, arguments);
        },
        onRender: function () {
            this.ui.collapseButton.on("click", _.bind(this._triggerCollapse, this));
        },
        _triggerCollapse: function () {
            this.trigger('toggle');
        },

        onKeyInView: function (event) {
            let keyCode = event.keyCode;
            this.isKeyEvent = true;
            switch (keyCode) {
                case 27:
                    this.trigger("toggle");
                    event.preventDefault();
                    event.stopPropagation();
                    break;
                default:
                    return;
            }
        }
    });

    return SmartPanelHeaderView;
});

csui.define('css!smart/controls/app.header/panel/groups/impl/smart.theme.groups',[],function(){});

/**
 * As this is experimental feature, once it is moved to leading appliction,
 * then proper animation should be applied, until then, let's keep the below
 * setTimeout for animation while switching the themes.
 */
csui.define('smart/controls/app.header/panel/groups/smart.theme.group',[
    'module',
    'smart/themes/theming',
    'css!smart/controls/app.header/panel/groups/impl/smart.theme.groups'
], function (module, theming) {
    const applyStyling = (method, className, timeOut) => {
        setTimeout(function () {
            document.body.classList[method](className);
        }, timeOut);
    };
    const processItem = (newTheme, args) => {
        let currentTheme = theming.getTheme();
        const isSwitchBetweenJatoAndNonJato = currentTheme === 'cf' || newTheme === 'cf';
        const clsName = isSwitchBetweenJatoAndNonJato ? 'smart-fade-out-and-in-long-time' : 'smart-fade-out-and-in';
        if (currentTheme !== newTheme) {
            applyStyling('add', clsName, 0);
            setTimeout(function () {
                theming.saveTheme(newTheme);
                theming.applyTheme();
                if (isSwitchBetweenJatoAndNonJato) {
                    args.context?.navigationHeaderView?.render();
                    // TODO: check for better approach than this tweak.
                    args.context?.trigger("exit:edit:perspective", newTheme);
                }
                args.context?.trigger("theme:switched", newTheme);
            }, 500);
            applyStyling('remove', clsName, 2500);
        } else {
            return false;
        }
    };
    const checkActive = (theme) => {
        let data = theming.getTheme();
        return data === theme;
    };

    const groups = [{
        id: "smartThemePanel",
        name: "Select theme (Experimental feature):",
        sequence: 9999
    }];

    const items = [{
        groupBy: "smartThemePanel",
        sequence: 1,
        name: "Carbonfibre (Default)",
        signature: "cf",
        execute: (args) => {
            processItem('cf', args);
        },
        isActive: () => {
            return checkActive('cf');
        }
    }, {
        groupBy: "smartThemePanel",
        sequence: 2,
        name: "Dark (JATO)",
        signature: "dark",
        execute: (args) => {
            processItem('dark', args);
        },
        isActive: () => {
            return checkActive('dark');
        }
    }, {
        groupBy: "smartThemePanel",
        sequence: 3,
        name: "Light (JATO)",
        signature: "light",
        execute: (args) => {
            processItem('light', args);
        },
        isActive: () => {
            return checkActive('light');
        }
    }
    ];

    return {
        groups,
        items
    };
});

/**
 * It has two regions, one is search and other one is list.
 */
csui.define('smart/controls/app.header/panel/groups/groups.view',[
    "nuc/lib/jquery",
    "nuc/lib/underscore",
    "nuc/lib/backbone",
    "nuc/lib/marionette3",
    "hbs!smart/controls/app.header/panel/groups/impl/groups",
    "smart/controls/app.header/panel/groups/groups.list/groups.list.view",
    "smart/controls/app.header/panel/header/header.view",
    "smart/controls/app.header/panel/groups/smart.theme.group",
    "smart/controls/progressblocker/blocker",
    "smart/themes/theming",
    "i18n!smart/controls/app.header/impl/nls/lang",
    'smart/lib/binf/js/binf',
], function ($, _, Backbone, Marionette, template, GroupsListView,
    PanelHeaderView, SmartPanelGroup, BlockingView, theming, lang) {
    "use strict";

    let SmartPanelGroupsView = Marionette.View.extend({

        template,

        className: "smart-groups-wrapper csui-normal-scrolling",

        ui: {
            header: '.smart-groups-header-wrapper',
            //searchInput: '.smart-groups-menu-search',
            list: '.smart-groups-list-wrapper'
        },
        events: {
            keydown: "onKeyInView",
        },

        constructor: function SmartPanelGroupsView(options = {}) {
            Marionette.View.apply(this, arguments);
            BlockingView.imbue(this);
        },

        templateContext: function () {
            return {
                mainNavigationAria: lang.mainNavigationAria
            };
        },
        onRender: function () {
            this.blockActions();
            if (!theming.isJATOTheme()) {
                // apply background color style using branding config.
                let bgColor = this.options.originatingView?.brandingConfig?.attributes?.brandingSettingCodes?.customBrandingBgColor ?? '';
                if (bgColor.length > 1) {
                    this.el.style.backgroundColor = bgColor;
                }
            }

            this.panelHeaderView = new PanelHeaderView(this.options);
            let headerRegion = new Marionette.Region({ el: this.ui.header });
            headerRegion.show(this.panelHeaderView);
            this.listenTo(this.panelHeaderView, 'toggle', _.bind(function (args) {
                this.trigger("close:panel");
            }, this));

            //this.ui.searchInput.on('change', _.bind(this._filterGroupItems, this));
            this.listenTo(this.options.originatingView, 'sync:data', _.bind(function (data) {
                this.unblockActions();
                this.options.collection = this._preparePanelCollection(data);
                this.groupListView = new GroupsListView(this.options);
                let region = new Marionette.Region({ el: this.ui.list });
                region.show(this.groupListView);
                this?.el.querySelector(".smart-card-visible")?.focus();
            }, this));
            this.options.originatingView.trigger('request:data');
        },

        _preparePanelCollection: function (data) {
            let groups = data.groups ?? [];
            let items = data.items ?? [];
            if (theming.isThemeSelectionEnabled()) {
                groups = [...groups, ...SmartPanelGroup.groups];
                items = [...items, ...SmartPanelGroup.items];
            }
            let collection = new Backbone.Collection([], {
                comparator: "sequence",
            });

            items.forEach(function (item) {
                if (item?.groupBy?.trim().length > 0) {
                    let groupId = item.groupBy;
                    let groupItem = collection.findWhere({ id: groupId });
                    if (groupItem) {
                        groupItem.attributes.groupItems.push(item);
                    } else {
                        let groupInfo = groups[_.findIndex(groups, { id: groupId })];
                        let newGroup = {
                            groupItems: [item]
                        };
                        collection.add({ ...groupInfo, ...newGroup });
                    }
                } else {
                    item.type = "standalone";
                    collection.add(item);
                }
            });
            this.collection = collection;
            return this.collection;
        },

        onKeyInView: function (event) {
            let keyCode = event.keyCode,
                currEle = event.target;
            this.isKeyEvent = true;
            switch (keyCode) {
                case 9:
                    var firstCardItem = this.el.querySelector(".smart-card-visible");
                    if (!(currEle == firstCardItem && event.shiftKey) &&
                        currEle?.classList?.contains("smart-card-visible")
                        || (event.shiftKey && currEle?.classList?.contains("smart-app-header-burger-close-btn"))) {
                        this.trigger("close:panel");
                        event.stopPropagation();
                        if (event.shiftKey) {
                            event.preventDefault();
                        }
                    }
                    break;
                case 27:
                    this.trigger("close:panel");
                    event.stopPropagation();
                    event.preventDefault();
                    break;
                default:
                    return;
            }
        },
        /*         _filterGroupItems: function (event) {
                    let searchValue = (this.ui.searchInput[0]?.value?.trim() ?? '').toLowerCase();
                    this.groupListView.trigger("apply:filter", searchValue);
                } */
    });

    return SmartPanelGroupsView;
});

